    'admin_email.waf_notice_body' => 'यदि सहेजना एक <em>403 / पहुँच अस्वीकृत</em> त्रुटि के साथ अवरुद्ध हो जाता है, तो वेब एप्लिकेशन फ़ायरवॉल (WAF) टेम्पलेट सामग्री जैसे <code style="background: #fde68a; padding: 1px 4px; border-radius: 3px;">{{placeholders}}</code> या HTML मार्कअप को फ़्लैग कर रहा हो सकता है। यहाँ WAF अक्षम करें, अपने बदलाव करें, फिर समाप्त होने पर इसे फिर से सक्षम करें।',
