    'admin_fair-defaults.ai_analysis_help' => 'सक्षम होने पर, विश्लेषक सभी उपलब्ध वेंडर सुरक्षा डेटा (Shodan संकेत, UpGuard जोखिम, भेद्यता डेटा और वित्तीय संदर्भ) के आधार पर यथार्थवादी ALE, प्राथमिक/द्वितीयक हानि परिमाण और अनुशंसित साइबर बीमा कवरेज का अनुमान लगाने के लिए AI का उपयोग कर सकते हैं।',
    'admin_fair-defaults.ai_disabled_help' => 'AI-सहायता प्राप्त FAIR गणना के लिए एक AI प्लेटफ़ॉर्म (OpenWebUI या LibreChat) सक्षम होना आवश्यक है। पहले <a href="admin.php?section=ai-integration">AI Integration सेटिंग्स कॉन्फ़िगर करें</a>।',
    'admin_fair-defaults.ai_enable_checkbox_label' => 'AI-सहायता प्राप्त FAIR गणना सक्षम करें',
    'admin_fair-defaults.ai_enable_help' => 'FAIR विश्लेषण फ़ॉर्म में एक "AI-सहायता प्राप्त विश्लेषण" बटन जोड़ता है। AI वित्तीय जोखिम मानों का अनुमान लगाने के लिए सभी उपलब्ध वेंडर सुरक्षा इंटेलिजेंस (Shodan, UpGuard, CVE, प्रमाणन) के साथ FAIR मॉडल पद्धति का उपयोग करता है। विश्लेषक सहेजने से पहले AI अनुमानों की समीक्षा कर सकते हैं और उन्हें स्वीकार या अस्वीकार कर सकते हैं।',
