    'admin_shadow-saas-grip.abort_failed_prefix' => 'सिंक निरस्त करने में विफल: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'चल रहे Grip सिंक को निरस्त करें?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'चल रहे HERO सिंक को निरस्त करें?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security आपके वातावरण में SaaS-of-Record एप्लिकेशनों को खोजता है और निरंतर निगरानी करता है।
यह एकीकरण:<br><br>
<strong>&bull; Grip डेटा मिरर करता है:</strong> संपूर्ण SaaS / उपयोगकर्ता / अलर्ट सूची को <code>shadow_saas_grip_*</code> तालिकाओं में खींचता है।<br>
<strong>&bull; Shadow SaaS को हाइड्रेट करता है:</strong> प्रत्येक SaaS ऐप को मौजूदा Shadow SaaS सूची में प्रक्षेपित करता है, URL को उसके पंजीकरण योग्य डोमेन में सामान्यीकृत करता है ताकि विक्रेता मिलान CSV आयात की तरह ही काम करे।<br>
<strong>&bull; जोखिम ट्रैक करता है:</strong> Grip के जोखिम स्कोर, स्वीकृति टैग, OAuth-स्कोप गणना, AI-गहराई वर्गीकरण, MFA / SAML समर्थन, और प्राथमिक-संपर्क मेटाडेटा को बनाए रखता है।<br>
<strong>&bull; ताज़ा रहता है:</strong> कॉन्फ़िगर की गई cron अनुसूची पर पुनः चलता है; व्यवस्थापक ऊपर दिए गए "Run Now" बटन से तत्काल पृष्ठभूमि रन भी ट्रिगर कर सकते हैं।',
    'admin_shadow-saas-grip.about_grip_heading' => 'Grip एकीकरण के बारे में',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security आपके वातावरण में तृतीय-पक्ष SaaS विक्रेताओं और उन्हें प्रभावित करने वाली समस्याओं को खोजता है।
यह एकीकरण:<br><br>
<strong>&bull; HERO डेटा मिरर करता है:</strong> विक्रेता / समस्याएँ / प्रति-विक्रेता उपयोगकर्ताओं को <code>shadow_saas_hero_*</code> तालिकाओं में खींचता है।<br>
<strong>&bull; Shadow SaaS को हाइड्रेट करता है:</strong> प्रत्येक विक्रेता को पंजीकरण योग्य डोमेन द्वारा मौजूदा Shadow SaaS सूची में प्रक्षेपित करता है, ताकि मिलान CSV आयात की तरह ही काम करे।<br>
<strong>&bull; जोखिम ट्रैक करता है:</strong> प्रति विक्रेता सबसे खराब खुली समस्या से 1-5 जोखिम स्कोर व्युत्पन्न करता है (वही 1-5 पैमाना जो Grip उपयोग करता है) और विक्रेता की स्थिति और सहभागिता पहलुओं को दर्ज करता है।<br>
<strong>&bull; ताज़ा रहता है:</strong> साझा अनुसूचित पुनर्जलीकरण कार्य पर पुनः चलता है; व्यवस्थापक नीचे दिए गए "Run Now" बटन से तत्काल रन भी ट्रिगर कर सकते हैं।',
    'admin_shadow-saas-grip.about_hero_heading' => 'HERO एकीकरण के बारे में',
