    'admin_shadow-saas-grip.currently_holding_prefix' => 'वर्तमान में धारण किए हुए ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>Live</strong> प्रत्येक पृष्ठ के लिए Grip API को कॉल करता है (हमेशा वर्तमान, API पर अधिक भार)। <strong>Local (हाइड्रेटेड/कैश्ड)</strong> डेटाबेस में हाइड्रेटेड <code>shadow_saas_grip_*</code> तालिकाओं को परोसता है - API पर कम भार - और एक अनुपस्थित प्रति-ऐप स्नैपशॉट एक बार API से लाया जाता है, फिर कैश किया जाता है। Local मोड में, प्रत्येक सिंक डेटा को <strong>पूरी तरह ताज़ा</strong> करता है: Grip मिरर तालिकाएँ ट्रंकेट की जाती हैं और API से पुनः हाइड्रेट की जाती हैं।',
    'admin_shadow-saas-grip.data_source_label' => 'डेटा स्रोत',
