    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Grip Security सार्वजनिक API के लिए एंडपॉइंट सूची (सर्वर बेस <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, स्वतः-जनित OpenAPI 3.1)। FairTPRM सिंक <em>used by sync</em> के रूप में चिह्नित रीड (GET) एंडपॉइंट्स का उपभोग करता है; संपूर्ण सूची &mdash; जिसमें Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions, और AI&nbsp;Agents समूह शामिल हैं &mdash; नीचे दिए गए OpenAPI और Postman डाउनलोड में है। डोमेन निष्कर्षण URL को उनके पंजीकरण योग्य डोमेन में सामान्यीकृत करता है (उदा. <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>)।',
    'admin_shadow-saas-grip.grip_auth_help' => 'प्रमाणीकरण हेडर: <code>access-token: &lt;your-token&gt;</code>। Postman संग्रह का <code>accessToken</code> वेरिएबल <code>REPLACE_ME</code> पर सेट है; अनुरोध भेजने से पहले अपना टेनेंट टोकन प्रतिस्थापित करें।',
    'admin_shadow-saas-grip.grip_base_url_help' => '<code>/public/saas</code> पर आधारित टेनेंट-उपसर्ग वाला Grip URL (उदा. <code>https://tenant.dep.grip.security/public/saas</code>)। सहोदर एंडपॉइंट्स (<code>/public/users</code>, <code>/public/alerts</code>) इसी होस्ट से व्युत्पन्न होते हैं।',
    'admin_shadow-saas-grip.grip_base_url_label' => 'सर्वर (टेनेंट बेस URL)',
    'admin_shadow-saas-grip.grip_breach_help' => 'प्रत्येक अनुसूचित पुनर्जलीकरण (और नीचे दिए गए मैन्युअल <strong>Run&nbsp;Now</strong>) पर, Grip "Security Incident Detected" अलर्ट <a href="breach-alerts.php">Breach&nbsp;/&nbsp;Cyber Alerts</a> प्रणाली में लिखे जाते हैं (डुप्लिकेट हटाकर)। किसी ऑनबोर्ड किए गए विक्रेता के लिए ब्रीच उस विक्रेता से जुड़े होते हैं; ऐसे ऐप के लिए ब्रीच जिसका कोई ऑनबोर्ड विक्रेता नहीं है, फिर भी दर्ज किए जाते हैं और संभावित रूप से प्रभावित उपयोगकर्ताओं की संख्या के साथ <strong>Shadow&nbsp;SaaS</strong> के रूप में टैग किए जाते हैं। इसके लिए Grip सक्षम (ऊपर) <em>और</em> <a href="admin.php?section=email">Email &amp; Alerts</a> के अंतर्गत Breach&nbsp;/&nbsp;Cyber Alert सेटिंग आवश्यक है।',
