    'admin_shadow-saas-grip.hero_api_reference_intro' => 'इस एकीकरण द्वारा उपयोग किए गए HERO सार्वजनिक API के लिए एंडपॉइंट सूची। प्रमाणीकरण OAuth 2.0 client-credentials &rarr; Bearer टोकन है; सूची एंडपॉइंट कर्सर पृष्ठांकन का उपयोग करते हैं (<code>next_cursor</code> &rarr; <code>cursor</code>)।',
    'admin_shadow-saas-grip.hero_auth_help' => 'प्रमाणीकरण: सभी डेटा एंडपॉइंट्स पर <code>Authorization: Bearer &lt;token&gt;</code>। टोकन ~1 घंटे के बाद समाप्त हो जाते हैं।',
    'admin_shadow-saas-grip.hero_base_url_help' => 'HERO सार्वजनिक API बेस, उदा. <code>https://api.herosecurity.ai/stable</code>। एंडपॉइंट्स (<code>/v1/vendors</code>, <code>/v1/issues</code>) इसी होस्ट से व्युत्पन्न होते हैं।',
    'admin_shadow-saas-grip.hero_base_url_label' => 'सर्वर (बेस URL)',
