    'admin_shadow-saas-grip.hero_connection_heading' => 'HERO Security कनेक्शन',
    'admin_shadow-saas-grip.hero_disabled_grip' => ' Grip अक्षम कर दिया गया - एक समय में केवल एक ही प्रदाता सक्रिय हो सकता है।',
    'admin_shadow-saas-grip.hero_enable_help' => 'सक्षम होने पर, अनुसूचित और मांग-आधारित सिंक HERO से विक्रेता, समस्याएँ, और प्रति-विक्रेता उपयोगकर्ताओं को Shadow SaaS सूची में खींचते हैं। HERO सक्षम करने से Grip अक्षम हो जाता है - एक समय में केवल एक ही प्रदाता सक्रिय हो सकता है।',
    'admin_shadow-saas-grip.hero_ep_auth' => 'Bearer टोकन के लिए client_id + client_secret का विनिमय करें।',
