    'admin_shadow-saas-grip.hero_ep_vendors_list' => 'विक्रेता सूचीबद्ध करें (कर्सर पृष्ठांकित; <code>page_size</code> &le; 250)।',
    'admin_shadow-saas-grip.hero_mirror_issues_desc' => 'प्रति HERO सुरक्षा समस्या एक पंक्ति (प्रकार, गंभीरता, स्थिति, विक्रेता)।',
    'admin_shadow-saas-grip.hero_mirror_users_desc' => 'प्रति विक्रेता प्राथमिक संपर्क - सर्वाधिक ईमेल-गतिविधि वाला उपयोगकर्ता, जिसे संबंध प्रबंधक के रूप में उपयोग किया जाता है।',
    'admin_shadow-saas-grip.hero_mirror_vendors_desc' => 'प्रति HERO विक्रेता एक पंक्ति (स्थिति, पहलू, व्युत्पन्न 1-5 जोखिम स्कोर, पूर्ण पेलोड)।',
    'admin_shadow-saas-grip.hero_pacing_help' => 'HERO API कॉल की दर सीमित करता है (~60 अनुरोध प्रति मिनट, खाता-व्यापी)। ये नियंत्रित करते हैं कि प्रति-विक्रेता उपयोगकर्ता सिंक अपनी गति कैसे निर्धारित करता है।',
    'admin_shadow-saas-grip.hero_security_link' => 'HERO Security &rarr;',
