    'admin_shadow-saas-grip.hero_throttle_help' => 'प्रत्येक विक्रेता के उपयोगकर्ता अनुरोध के बीच रुकें। ~1100&nbsp;ms पूर्ण सिंक को HERO की ~60/min सीमा से ठीक नीचे रखता है। कम मान तेज़ है लेकिन दर-सीमा (429) बैकऑफ़ ट्रिगर करता है।',
    'admin_shadow-saas-grip.hero_throttle_label' => 'विक्रेता कॉल के बीच थ्रॉटल (ms)',
    'admin_shadow-saas-grip.hero_timeout_help' => 'किसी विक्रेता के उपयोगकर्ताओं को छोड़ने से पहले कितनी देर प्रतीक्षा करें। कम मान का अर्थ है कि जो बहुत बड़े टेनेंट अटक जाते हैं वे पूरे टाइमआउट के लिए रन को रोकने के बजाय शीघ्र विफल हो जाते हैं।',
