    'admin_shadow-saas-grip.sched_enable_help' => 'सक्षम होने पर, कार्य सिस्टम crontab में स्थापित होता है और नीचे दी गई अनुसूची पर चलता है। एक लॉक फ़ाइल ओवरलैपिंग रन को रोकती है। रन उसी प्रदाता का उपयोग करता है जो सक्षम है।',
    'admin_shadow-saas-grip.sched_rehydration_heading' => 'अनुसूचित पुनर्जलीकरण',
    'admin_shadow-saas-grip.sched_rehydration_intro' => 'सक्षम Shadow SaaS प्रदाता (Grip या Hero) को एक अनुसूची पर चलाता है, मिरर तालिकाओं और Shadow SaaS सूची को ताज़ा करता है। नीचे दी गई अनुसूची स्वचालित रूप से सिस्टम crontab में स्थापित हो जाती है &mdash; कोई मैन्युअल crontab संपादन नहीं, और यह कंटेनर पुनरारंभ के बाद भी बनी रहती है।',
