    'admin_shadow-saas-grip.zscaler_config_updated' => 'Zscaler कॉन्फ़िगरेशन सफलतापूर्वक अद्यतन किया गया।',
    'admin_shadow-saas-grip.zscaler_connection_heading' => 'Zscaler कनेक्शन',
    'admin_shadow-saas-grip.zscaler_enable_help' => 'सक्षम होने पर, Shadow SaaS में Deny बटन विक्रेता के डोमेन को कॉन्फ़िगर की गई URL श्रेणी में पुश करेगा। अक्षम होने पर, Deny केवल स्थानीय स्थिति अद्यतन करता है।',
    'admin_shadow-saas-grip.zscaler_intro' => 'जब किसी विक्रेता को Shadow SaaS सूची से अस्वीकार किया जाता है, तो विक्रेता का डोमेन नीचे दी गई URL श्रेणी में Zscaler ZIA में जोड़ा जाता है (<code>action=ADD_TO_LIST</code> का उपयोग करके), फिर सक्रिय किया जाता है। दोनों प्रदाताओं द्वारा साझा किया गया।',
