    'admin_shadow-saas-grip.zscaler_vanity_label' => 'ZIdentity वैनिटी डोमेन',
    'admin_shodan-srs.about_body' => 'Shodan एक इंटरनेट इंटेलिजेंस प्लेटफ़ॉर्म है जो हर इंटरनेट-कनेक्टेड डिवाइस को स्कैन और अनुक्रमित करता है जिसे वह खोज सकता है। यह एकीकरण सक्षम करता है:<br><br><strong>• पोर्ट स्कैनिंग:</strong> वेंडर इंफ्रास्ट्रक्चर पर खुले पोर्ट की पहचान करें, जिसमें उच्च-जोखिम वाली सेवाएं शामिल हैं (FTP, Telnet, RDP, SMB)<br><strong>• भेद्यता पहचान:</strong> वेंडर IP पतों और सेवाओं से जुड़े ज्ञात CVE खोजें<br><strong>• सेवा पहचान:</strong> चल रही सेवाओं, सॉफ़्टवेयर संस्करणों और सर्वर कॉन्फ़िगरेशन को सूचीबद्ध करें<br><strong>• सुरक्षा स्कोरिंग:</strong> उजागर हमले की सतह के आधार पर 0-100 सुरक्षा स्कोर उत्पन्न करें',
    'admin_shodan-srs.about_heading' => 'Shodan के बारे में',
    'admin_shodan-srs.about_learn_more' => 'Shodan के बारे में और जानें →',
    'admin_shodan-srs.about_note_body' => 'Shodan स्कोर UpGuard स्कोर के पूरक हैं। UpGuard समग्र सुरक्षा स्थिति (0-950 पैमाने) पर केंद्रित है, जबकि Shodan उजागर इंफ्रास्ट्रक्चर (0-100 पैमाने) पर केंद्रित है। व्यापक वेंडर मूल्यांकन के लिए दोनों को एक साथ सक्षम किया जा सकता है।',
