    'admin_shodan-srs.on_demand_help' => 'सक्षम होने पर, Shodan स्कोरिंग के दौरान किसी भी ऐसे IP के लिए ऑन-डिमांड स्कैन का अनुरोध करेगा जिसके लिए उसके पास कोई मौजूदा डेटा नहीं है। यह उन डोमेन के लिए कवरेज सुनिश्चित करता है जिन्हें Shodan ने पहले स्कैन नहीं किया है, लेकिन यह स्कैन क्रेडिट का उपयोग करता है (प्रति IP 1 क्रेडिट) और जब Shodan स्कैन को संसाधित करता है तो प्रति स्कोरिंग अनुरोध पर 3 मिनट तक की प्रतीक्षा अवधि जोड़ता है। उन वेंडरों के लिए अनुशंसित जहां Shodan कोई सुरक्षा सिग्नल नहीं लौटाता।',
