    'admin_shodan-srs.word_waiver' => 'छूट',
    'admin_shodan-srs.word_waivers' => 'छूटें',
    'admin_srs.about_custom_body' => 'कस्टम स्कोरिंग आपको बाहरी मूल्यांकन उपकरणों या रेटिंग सेवाओं का उपयोग करके वेंडरों के लिए सुरक्षा स्कोर मैन्युअल रूप से दर्ज करने की अनुमति देती है।<br><br><strong>स्कोर श्रेणी:</strong> 1-100 (प्रतिशत पैमाना)<br><strong>ग्रेडिंग:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>जब कई स्कोरिंग स्रोत मौजूद होते हैं (UpGuard, Shodan, Custom), तो एक संयुक्त औसत स्कोर की गणना की जाती है और पूरे एप्लिकेशन में प्रदर्शित किया जाता है। यह सभी उपलब्ध स्रोतों से प्रत्येक वेंडर के सुरक्षा रुख का एकीकृत दृश्य प्रदान करता है।',
    'admin_srs.about_custom_heading' => 'कस्टम स्कोरिंग के बारे में',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk तृतीय-पक्ष वेंडरों के लिए स्वचालित सुरक्षा रेटिंग और निरंतर निगरानी प्रदान करता है। यह एकीकरण सक्षम करता है:<br><br><strong>• स्वचालित सुरक्षा स्कोरिंग:</strong> वेंडरों के बाहरी सुरक्षा रुख के आधार पर तत्काल सुरक्षा रेटिंग (0-950) प्राप्त करें<br><strong>• जोखिम पहचान:</strong> उच्च, मध्यम, और निम्न गंभीरता के सुरक्षा जोखिमों को स्वचालित रूप से पहचानें<br><strong>• प्रवृत्ति विश्लेषण:</strong> सुधार या गिरावट की पहचान के लिए समय के साथ वेंडर सुरक्षा स्कोर को ट्रैक करें<br><strong>• टियर-आधारित निगरानी:</strong> वेंडर महत्ता के आधार पर पुनर्स्कोरिंग आवृत्ति कॉन्फ़िगर करें',
    'admin_srs.about_upguard_heading' => 'UpGuard CyberRisk के बारे में',
