    'admin_srs.cron_ondemand_desc' => 'वेंडर विवरण पृष्ठ से कतारबद्ध मैन्युअल पुनर्स्कोर अनुरोधों को संसाधित करता है। किसी भी एकीकरण पर जब "पुनर्स्कोरिंग के लिए Cron का उपयोग करें" सक्षम होता है तो <strong>आवश्यक</strong>:',
